def seed_modalities(apps, schema_editor):
    """Classify the seeded radiology catalogue by imaging modality once.

    Queues route on explicit department/modality from now on; this only tags
    historical catalogue rows so the X-Ray and USG tabs are useful on day one.
    """
    Definition = apps.get_model("patients", "ServiceDefinition")
    for definition in Definition.objects.select_related("department").filter(
        department__slug="radiology"
    ).iterator():
        name = definition.name.casefold()
        if any(token in name for token in ("usg", "ultrasound", "sonograph")):
            modality = "usg"
        elif any(token in name for token in ("x-ray", "xray")):
            modality = "xray"
        else:
            modality = ""
        Definition.objects.filter(pk=definition.pk).update(modality=modality)


